-- Prima infornata dal nuovo libro "Enciclopedia delle Piante in Vaso"
-- (collana Fiori & Piante) — #120 espansione catalogo. A differenza del
-- volume precedente (piante da interno), questo libro tratta piante da
-- vaso per esterno/balcone/giardino: dimensioni, resistenza al gelo e
-- vaso.dimensione_minima_litri sono quindi più generosi rispetto alle
-- voci da appartamento.
--
-- 6 nuove specie: Abutilon, Acacia, Agapanthus, Arbutus, Cavolo
-- ornamentale (Brassica oleracea), Brugmansia.
--
-- Agave (stessa pagina) è stata SALTATA: già presente e verificata nel
-- catalogo (fonte RHS).
--
-- Cavolo ornamentale: usato lo slug "cavolo-ornamentale" per non
-- confliggere con la voce "cavolo" già presente (varietà alimentare);
-- qui si tratta della forma ornamentale di B. oleracea, coltivata per
-- il fogliame decorativo.
--
-- Brugmansia: segnalata pianta velenosa (simbolo "!" esplicito nel
-- libro). Nota tassonomica esplicitata dalla fonte stessa: il genere
-- era storicamente incluso in Datura.
--
-- Agapanthus: nota tassonomica aggiunta — collocazione familiare
-- variabile tra le fonti (Amaryllidaceae vs Agapanthaceae).
--
-- giorni_germinazione/giorni_trapianto/giorni_raccolta e npk lasciati
-- null per tutte le specie: il libro non fornisce questi dati.

insert into specie
  (nome, nome_scientifico, famiglia_botanica, descrizione, esigenze, alert, manutenzione, ciclo_colturale, vaso, ciclo_vitale, slug, fonti, stato_verifica, verificata_il, verificata_da)
values
($t$Abutilon$t$, $t$Abutilon x hybridum$t$, $t$Malvaceae$t$, $t$Abutilon, un genere originario delle regioni tropicali e subtropicali dell'America centrale e meridionale, comprende arbusti con ramificazioni sottili e allungate, foglie sparse, cordiformi, palmate, seghettate, fiori con peduncolo sottile, ascellari, solitari, di colore rosso, giallo o arancione, con calice campanulato composto di 5 parti, e splendidi stami fusi e sporgenti; i fiori rimangono aperti per due giorni. Alcune specie hanno foglie screziate. A. megapotamicum ha fiori penduli con calice rosso, corolla gialla e stami quasi neri; 'Variegatum' ha foglie maculate di un giallo chiaro. A. striatum (sin. A. pictum), che fiorisce da agosto a settembre, è una specie molto vigorosa (soprattutto la varietà 'Thompsonii', con fiori di color salmone e foglie maculate gialle). Gli ibridi del genere sono incroci ottenuti da diverse specie naturali, di solito con foglie completamente verdi e fiori gialli, arancioni, rossi, rosa, bianchi. 'Feuerglocke' ha fiori rossi; 'Golden Fleece' ha fiori giallo scuro; 'Boule de Neige' ha fiori bianchi; 'Ashford Red' ha fiori rosa salmone-brunastri.$t$, $j${"luce": "Luminosa, ma riparata dai raggi diretti del sole", "acqua": "Abbondante nella stagione calda", "terreno": "Normale terriccio da vasi"}$j$::jsonb, ARRAY[$t$i fiori rimangono aperti per due giorni$t$, $t$i vasi piuttosto piccoli favoriscono la fioritura$t$, $t$i fusti esili vanno legati$t$, $t$se necessario, per ottenere uno sviluppo cespuglioso, cimare i germogli di tanto in tanto$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "abbondante", "estate": "abbondante", "autunno": "diradare (periodo di riposo da settembre a marzo)", "inverno": "ridotta, temperatura superiore ai 12°C"}, "concimazione": {"primavera": "una volta alla settimana", "estate": "una volta alla settimana", "autunno": "sospesa (settembre-marzo)", "inverno": "sospesa"}, "potatura": {"primavera": "potare e rinvasare a inizio primavera in normale terriccio da vasi", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Malvaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 50, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 5, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.85}$j$::jsonb, $t$perenne$t$, $t$abutilon$t$, ARRAY[$t$Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Acacia$t$, $t$Acacia dealbata$t$, $t$Fabaceae$t$, $t$Il genere Acacia comprende molte specie diffuse nelle regioni aride dell'Australia tropicale, dell'Asia e dell'Africa. Alcune specie dei generi Mimosa e Robinia vengono talvolta inserite erroneamente nel genere Acacia (la mimosa comune è in effetti una specie di Acacia, ma altre 'mimose' non lo sono). Dalle specie A. dealbata, A. decurrens e A. baileyana sono stati ottenuti molti ibridi dai fiori profumati che vengono venduti come fiori recisi. Si tratta di specie arboree e arbustive, con rami in genere spinosi e foglie pennate o composte che si ripiegano quando vi è una variazione di luce o di temperatura. A. armata è un arbusto ramificato, spinoso, con foglie a picciolo appiattito e fiori di un giallo brillante in capolini globosi. A. baileyana ha foglie bipennate, numerosissimi fiori in capolini pedicellati, lunghi 10cm; le foglie della A. baileyana 'Purpurea' hanno una tinta purpurea. A. dealbata è un albero con foglie bipennate, di colore verde-grigiastro e fiori profumati, gialli, in capolini globosi; la pianta ha una fioritura precoce (da gennaio ad aprile) ed è eccellente per fiori recisi. A. longifolia ha foglie intere, oblunghe e fiori in capolini disposti in infiorescenze cilindriche lunghe 2,5-5cm. A. verticillata ha foglie lineari acuminate e fiori di un bel giallo brillante in spighette cilindriche; questa specie è resistente al vento marino salato, al calcare e all'umidità.$t$, $j${"luce": "Molto luminosa o soleggiata", "acqua": "Terreno sempre umido ma non troppo bagnato, soprattutto in estate; molta aria", "terreno": "Ricco di humus"}$j$::jsonb, ARRAY[$t$alcune specie dei generi Mimosa e Robinia vengono talvolta inserite erroneamente nel genere Acacia (la mimosa comune è in effetti una specie di Acacia, ma altre "mimose" non lo sono)$t$, $t$eccellente per fiori recisi (in particolare A. dealbata)$t$, $t$per favorire la fioritura, far svernare le piante in un locale a 4-6°C$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "terreno sempre umido ma non troppo bagnato", "estate": "terreno sempre umido ma non troppo bagnato, molta aria", "autunno": "normale", "inverno": "svernare a 4-6°C per favorire la fioritura"}, "concimazione": {"primavera": "abbondante nel periodo vegetativo", "estate": "abbondante nel periodo vegetativo", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "potare subito dopo la fioritura; rinvasare se necessario in terriccio da vasi normale ben premuto", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Fabaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "bassa", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 10, "rinvaso_ogni_mesi": 24, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$acacia$t$, ARRAY[$t$Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Agapanthus$t$, $t$Agapanthus africanus$t$, $t$Amaryllidaceae$t$, $t$Agapanthus (nome che in greco significa 'fiore dell'amore') è un genere originario dell'Africa australe e comprende 10 specie (note come amarillide turchina). Si tratta di piante erbacee con radici carnose, foglie inguainanti di un verde scuro, lunghe 40-60cm e fiori imbutiformi, blu o bianchi, in ombrelle terminali sorrette da lunghi scapi fiorali lisci. A. africanus ha fusti lunghi 60-90cm, con grandi ombrelle di fiori di colore blu e, in un secondo tempo, bei frutti a capsula; vi sono anche varietà dai fiori bianchi. A. campanulatus, alto 73cm, ha foglie caduche e fiori di un blu chiaro; può essere coltivata anche all'aperto; 'Isis' ha fiori color lavanda. A. praecox ha foglie persistenti e soffre il gelo; ha scapi fiorali lunghi più di 100cm, foglie lunghe 50-60cm riunite in rosette basali, grandi ombrelle di fiori blu chiaro ed è ottima per fiori recisi. Gli ibridi ottenuti dalle varie specie sono numerosi e, di solito, soffrono il gelo; 'Blue Giant', alto sino a 110cm, ha grandi ombrelle di fiori blu.$t$, $j${"luce": "Pieno sole", "acqua": "Abbondante in estate, diradata dopo la fioritura, quasi sospesa in inverno", "terreno": "Sostanzioso e ben drenato, arricchito con argilla e concime"}$j$::jsonb, ARRAY[$t$nome comune "amarillide turchina"$t$, $t$nota tassonomica: la classificazione familiare è variabile, talvolta collocato in Amaryllidaceae, talvolta in una famiglia propria (Agapanthaceae)$t$, $t$attira le farfalle$t$, $t$risulta valorizzato se coltivato in gruppo in un grande vaso$t$, $t$dopo aver vegetato per molti anni nello stesso vaso, la fioritura sarà più abbondante$t$, $t$tollera temperature appena al di sotto dello 0°C ed è resistente al vento$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "abbondante", "autunno": "diradata dopo la fioritura", "inverno": "quasi sospesa"}, "concimazione": {"primavera": "regolare", "estate": "regolare", "autunno": "quasi sospesa", "inverno": "quasi sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Amaryllidaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": [], "resistenza_gelo": "bassa", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 10, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.85}$j$::jsonb, $t$perenne$t$, $t$agapanthus$t$, ARRAY[$t$Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Arbutus$t$, $t$Arbutus unedo$t$, $t$Ericaceae$t$, $t$Arbutus è un genere spontaneo nell'Europa meridionale e comprende soltanto 3 specie arboree o arbustive non molto resistenti al freddo. Queste piante hanno foglie coriacee, ovali, lucide, di colore verde, con margine appena dentellato, fiori bianco-crema, a forma di vaso, in pannocchie e bei frutti globosi di colore rosso-aranciato che si mantengono sull'albero anche durante la fioritura successiva. A. andrachne, in genere perenne, è alto sino a 5m, e ha la corteccia screpolata, rossastra, pannocchiette erette, e frutti globosi lisci; questa pianta è di difficile coltivazione. A. x andrachnoides, ibrido ottenuto dall'incrocio di A. andrachne e A. unedo, ha caratteristiche variabili e, solitamente, presenta ramificazioni numerose, corteccia rossastra e fioritura duratura; questo ibrido cresce bene anche in terreno leggermente calcareo. A. unedo, corbezzolo, è una pianta perenne moderatamente resistente al freddo, alta 5-12m, con fiori di colore giallo-aranciato, in racemi, e frutti a bacca rossi, ruvidi; 'Rubra' ha fiori rosa; 'Rubra compact' ha fiori con una tinta rosata. La pianta forma stoloni e tollera bene un terreno non molto calcareo.$t$, $j${"luce": "Soleggiata, posizione riparata", "acqua": "Regolare, senza eccedere", "terreno": "Preferibilmente acido, o leggermente calcareo, ben drenato"}$j$::jsonb, ARRAY[$t$A. unedo, il corbezzolo, è la specie più nota, spontanea anche in Italia$t$, $t$A. andrachne è di difficile coltivazione$t$, $t$i frutti globosi rosso-aranciati si mantengono sulla pianta anche durante la fioritura successiva$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "regolare, senza eccedere", "estate": "regolare, senza eccedere", "autunno": "regolare, senza eccedere", "inverno": "diradata, senza lasciare asciugare la terra"}, "concimazione": {"primavera": "una volta ogni 15 giorni", "estate": "una volta ogni 15 giorni", "autunno": "una volta ogni 15 giorni", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Ericaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["marzo", "aprile"], "resistenza_gelo": "media", "spaziatura_cm": 300, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 15, "rinvaso_ogni_mesi": 24, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$arbutus$t$, ARRAY[$t$Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Cavolo ornamentale$t$, $t$Brassica oleracea$t$, $t$Brassicaceae$t$, $t$Il genere Brassica comprende numerose specie, molte delle quali sono diffuse come ortaggi (cavoli e rape), provenienti dalle regioni temperate dell'Europa e dell'Asia. B. oleracea, cavolo, è una pianta annuale con fiori bianchi; questa specie include varietà coltivate a scopo alimentare e altre ornamentali, apprezzabili per le belle foglie, con margini frastagliati o lisci, i cui colori vanno dal verde e bianco con centro giallo o rosso al porpora e bianco. In inverno, i cavoli ornamentali danno un tocco di colore, se posti sui davanzali. Queste piante tollerano piuttosto bene il freddo, ma non altrettanto il gelo; il freddo intenso rende più vivo il colore delle foglie.$t$, $j${"luce": "Pieno sole o leggermente in ombra", "acqua": "Regolare; terra sostanziosa mantenuta umida", "terreno": "Sostanziosa e ben drenata"}$j$::jsonb, ARRAY[$t$coltivata come pianta ornamentale per le foglie decorative, non per i fiori (distinta dalle varietà alimentari del cavolo comune, già presenti in catalogo)$t$, $t$il freddo intenso rende più vivo il colore delle foglie$t$, $t$sfoltire le pianticelle dopo la semina$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "regolare", "inverno": "regolare, tollera bene il freddo ma non il gelo"}, "concimazione": {"primavera": null, "estate": null, "autunno": null, "inverno": null}, "potatura": {"primavera": null, "estate": null, "autunno": null, "inverno": null}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Brassicaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["aprile", "maggio"], "finestra_trapianto": ["agosto", "settembre"], "resistenza_gelo": "media", "spaziatura_cm": 60, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 3, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.8}$j$::jsonb, $t$annuale$t$, $t$cavolo-ornamentale$t$, ARRAY[$t$Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Brugmansia$t$, $t$Brugmansia suaveolens$t$, $t$Solanaceae$t$, $t$Brugmansia (sin. Datura) è un genere originario dell'America centrale e meridionale e comprende specie arboree e arbustive. Queste specie sono simili a quelle di Datura, genere a cui in passato erano ascritte e che oggi include le forme più erbacee. Si tratta di piante velenose dalle grandi foglie, con fiori profumati, imbutiformi, penduli, di colore bianco, giallo o arancione. Gli incroci sono comuni. B. sanguinea (sin. Datura sanguinea), alta 1-1,5m, ha una chioma folta, composta di foglie ovali, pubescenti, e fiorisce tutto l'anno, soprattutto in inverno, con fiori inodori, lunghi 20cm, di colore rosso-aranciato. B. suaveolens (sin. Datura suaveolens), alta sino a 5m, ha foglie ovato-oblunghe, lunghe 15-30cm, leggermente pubescenti sulla pagina inferiore e fiori penduli, profumati, imbutiformi, con corolla stellata, lunghi 25-30cm; 'Plena' ha fiori doppi bianchi; 'Rosa' ha fiori rosa.$t$, $j${"luce": "Pieno sole, posizione calda e riparata", "acqua": "Abbondante in estate", "terreno": "Sostanzioso, arricchito con argilla e concime"}$j$::jsonb, ARRAY[$t$pianta velenosa (simbolo "!" esplicito nel libro): va posta fuori dalla portata dei bambini$t$, $t$nota tassonomica: il genere era storicamente incluso in Datura, da cui il sinonimo ancora diffuso in commercio; oggi Datura include le forme più erbacee$t$, $t$crescita rapida: è preferibile coltivarla in vasi grandi$t$, $t$moltiplicazione per talee legnose in febbraio, da interrare in un composto di sabbia e torba e conservare a 20°C$t$], $j${"irrigazione": {"primavera": "abbondante", "estate": "abbondante, posizione calda riparata e arieggiata, in pieno sole", "autunno": "diradare le innaffiature", "inverno": "terra piuttosto asciutta, riposo a 7°C (10-15°C per le piante giovani)"}, "concimazione": {"primavera": "non più di una volta alla settimana", "estate": "non più di una volta alla settimana", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Solanaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 200, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 15, "rinvaso_ogni_mesi": 24, "irrigazione_fattore": 0.85}$j$::jsonb, $t$perenne$t$, $t$brugmansia$t$, ARRAY[$t$Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$);
